mapper.select:
SELECT pap.id, pap.assessment_name, p.name as patient_name, p.gender, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) as age, p.medical_record_no as medical_record_number, p.disease_type, p.enrollment_institution, pap.execution_institution, pap.status, pap.prescribing_doctor, pap.created_time, pap.updated_time FROM patient_assessment_plan pap LEFT JOIN patient p ON pap.patient_id = p.id
AND p.disease_type = #{query.diseaseType}
AND pap.status = #{query.status}
AND p.enrollment_institution = #{query.enrollmentInstitution}
AND pap.prescribing_doctor = #{query.prescribingDoctor}
AND ( p.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%') )
ORDER BY pap.created_time DESC
